async def act(page):
    """
    - Close any blocking popup if present.
    - Scan up to 7 pages of the Customers grid for the telephone 555-229-3326.
    - When found, extract Name (cell index 2) and Email (cell index 3) from the matching row
      and print exactly: "Name, email".

    Notes on KB functions:
    - The knowledge-base provides export_customers_csv_via_grid which would let us export the entire
      customers grid to CSV and search it in one step. However, that helper is disabled/unavailable
      in this environment, so this function searches the visible grid and paginates instead.
    """
    import re
    import asyncio

    target_raw = "555-229-3326"
    formatted_re = re.compile(r"555\D*229\D*3326")
    digits_re = re.compile(re.escape(''.join(ch for ch in target_raw if ch.isdigit())))

    async def close_popup_if_any():
        # Try common close button accessible names first
        try:
            close_btns = page.get_by_role("button", name=re.compile(r"^\u00d7$|^×$|^x$|close|dismiss|ok", re.I))
            if await close_btns.count() > 0:
                try:
                    await close_btns.first.click()
                    await asyncio.sleep(0.25)
                    return True
                except Exception:
                    pass
        except Exception:
            pass

        # Fallback: try to click any button inside a dialog or alert
        try:
            dialogs = page.get_by_role("dialog")
            if await dialogs.count() > 0:
                btns = dialogs.first.get_by_role("button")
                n = await btns.count()
                for i in range(n):
                    try:
                        await btns.nth(i).click()
                        await asyncio.sleep(0.25)
                        return True
                    except Exception:
                        pass
        except Exception:
            pass

        try:
            alerts = page.get_by_role("alert")
            if await alerts.count() > 0:
                btns = alerts.first.get_by_role("button")
                n = await btns.count()
                for i in range(n):
                    try:
                        await btns.nth(i).click()
                        await asyncio.sleep(0.25)
                        return True
                    except Exception:
                        pass
        except Exception:
            pass

        # Last-resort: try clicking any visible '×' text
        try:
            x = page.get_by_text("×")
            if await x.count() > 0:
                try:
                    await x.first.click()
                    await asyncio.sleep(0.25)
                    return True
                except Exception:
                    pass
        except Exception:
            pass

        return False

    # There are 7 pages indicated in the UI; scan up to that many pages.
    max_pages = 7
    for _ in range(max_pages):
        await close_popup_if_any()
        await asyncio.sleep(0.2)

        # Try formatted display match first, then digits-only, then exact raw string as fallback.
        rows = None
        try:
            rows = page.get_by_role("row").filter(has=page.get_by_text(formatted_re))
            if await rows.count() == 0:
                rows = page.get_by_role("row").filter(has=page.get_by_text(digits_re))
            if await rows.count() == 0:
                rows = page.get_by_role("row").filter(has=page.get_by_text(target_raw))
        except Exception:
            try:
                rows = page.get_by_role("row").filter(has=page.get_by_text(target_raw))
            except Exception:
                rows = None

        if rows is not None and await rows.count() > 0:
            # Extract Name (cell index 2) and Email (cell index 3) per the accessibility tree
            row = rows.first
            cells = row.get_by_role("cell")
            cnt = await cells.count()
            name_text = ""
            email_text = ""
            if cnt > 2:
                try:
                    name_text = (await cells.nth(2).inner_text()).strip()
                except Exception:
                    name_text = ""
            if cnt > 3:
                try:
                    email_text = (await cells.nth(3).inner_text()).strip()
                except Exception:
                    email_text = ""

            # Print the single-line result exactly as requested and return
            print(f"{name_text}, {email_text}")
            return

        # Not found on current page: click the scoped "Go to Next page" link and continue
        try:
            pagination_row = page.get_by_role("row").filter(
                has=page.get_by_role("link", name=re.compile(r"Go to Next page", re.I))
            )
            if await pagination_row.count() > 0:
                next_link = pagination_row.first.get_by_role("link", name=re.compile(r"Go to Next page", re.I))
            else:
                next_link = page.get_by_role("link", name=re.compile(r"Go to Next page", re.I))

            if await next_link.count() > 0:
                await close_popup_if_any()
                await next_link.first.click()
                # Wait for grid to refresh
                await asyncio.sleep(0.8)
                continue
            else:
                break
        except Exception:
            # Try closing popup and retry once, otherwise stop searching
            await close_popup_if_any()
            try:
                next_link = page.get_by_role("link", name=re.compile(r"Go to Next page", re.I))
                if await next_link.count() > 0:
                    await next_link.first.click()
                    await asyncio.sleep(0.8)
                    continue
            except Exception:
                break

    # If not found after scanning pages, print an empty string as fallback
    print("")
